import "@stdlib/gas-payments"
import "send-to-c5"
import "revisions"
import "errors"
import "messages"
import "storage"

/// WalletTg, the Telegram Wallet contract, is a wallet whose bytecode is stored in config.
/// Its blockchain logic is shared by all Telegram users and atomically updated by validator voting.
contract WalletTg {
    author: "TON Core"
    version: "1.0"
    description: "Telegram wallet contract; bytecode stays in config and is updated by validator voting"
    storage: Storage
    incomingMessages: SignedRequest<AllowedInternalMsg>
    incomingExternal: SignedRequest<AllowedExternalMsg>
}

type AllowedInternalMsg =
    | SendOneMessageRequestI
    | SendBulkMessagesRequestI
    | ChangePublicKeyRequestI
type AllowedExternalMsg =
    | SendOneMessageRequestE
    | SendBulkMessagesRequestE
    | ChangePublicKeyRequestE

/// Validate the message header (present in all internal/external messages) against replay attacks.
@inline
fun SeqnoHeader.validateRequest(self, storage: Storage) {
    assert (self.seqno == storage.seqno) throw Errors.InvalidSeqno;
    assert (self.subwalletId == storage.subwalletId) throw Errors.InvalidSubwalletId;
    assert (self.validUntil > blockchain.now()) throw Errors.Expired;
}

/// Changing the wallet key requires a special "rotation proof" signed with the new private key.
fun checkRotationProof(rotationSignature: Cell<bits512>, newPublicKey: uint256): bool {
    // a "change key" message is signed by two keys:
    // 1) signature of the message itself (current key)
    // 2) a special "proof" signed by a new private key
    val (myWorkchain, myAddrHash) = contract.getAddress().getWorkchainAndHash();
    val expectedPayload = KeyRotationProofPayload {
        walletWorkchain: myWorkchain,
        walletAddrHash: myAddrHash,
    };
    return isSignatureValid(
        expectedPayload.toCell().hash(),    // the same payload is built by the client and signed
        rotationSignature.load() as slice,
        newPublicKey,
    );
}

@on_bounced_policy("manual")    // tell the compiler "don't insert code to filter out bounced messages"
fun onInternalMessage(in: InMessage) {
    // we should NOT throw until the signature proves that the owner signed the message;
    // WalletTrampoline already checked that `in.body` >= 512 bits;
    // in.body is `SignedRequest`: signature + rest, parse rest after checking
    val signature = in.body.loadBits(512);
    val rest = in.body;

    var storage = Storage.load();
    if (!isSignatureValid(rest.hash(), signature, storage.publicKey)) {
        return;
    }

    // after checking the signature, we may throw: if a message is invalid, it's still signed by the user
    val msg = lazy AllowedInternalMsg.fromSlice(rest);
    match (msg) {
        SendOneMessageRequestI => {
            msg.header.validateRequest(storage);

            storage.seqno += 1;
            storage.save();

            msg.msg.validateAndSend(false);
        }

        SendBulkMessagesRequestI => {
            msg.header.validateRequest(storage);

            storage.seqno += 1;
            storage.save();

            msg.msgArr.parseArrayAndSend(false);
        }

        ChangePublicKeyRequestI => {
            msg.header.validateRequest(storage);

            assert (storage.publicKey != msg.newPublicKey) throw Errors.NewKeyMustDiffer;
            assert (checkRotationProof(msg.rotationSignature, msg.newPublicKey)) throw Errors.NewKeySignatureIsInvalid;

            storage.seqno += 1;
            storage.publicKey = msg.newPublicKey;
            storage.save();
        }

        else => {
            throw Errors.InvalidOpcode;
        }
    }
}

fun onExternalMessage(inMsgBody: slice) {
    // unlike onInternalMessage, we may throw here;
    // WalletTrampoline did not check anything for external, load 512 may throw;
    // expect inMsgBody to be `SignedRequest`: signature + rest, parse rest after checking
    val signature = inMsgBody.loadBits(512);
    val rest = inMsgBody;

    var storage = Storage.load();
    if (!isSignatureValid(rest.hash(), signature, storage.publicKey)) {
        throw Errors.InvalidSignature;
    }

    val msg = lazy AllowedExternalMsg.fromSlice(rest);
    match (msg) {
        SendOneMessageRequestE => {
            msg.header.validateRequest(storage);
            acceptExternalMessage();

            storage.seqno += 1;
            storage.save();
            commitContractDataAndActions();

            msg.msg.validateAndSend(true);
        }

        SendBulkMessagesRequestE => {
            msg.header.validateRequest(storage);
            acceptExternalMessage();

            storage.seqno += 1;
            storage.save();
            commitContractDataAndActions();

            // if parsing fails, the contract throws, and its balance is charged for gas;
            // this is expected: if we are here, the user signed this incorrectly packed message;
            // anyway, it cannot be replayed, because seqno is already bumped
            msg.msgArr.parseArrayAndSend(true);
        }

        ChangePublicKeyRequestE => {
            msg.header.validateRequest(storage);

            assert (storage.publicKey != msg.newPublicKey) throw Errors.NewKeyMustDiffer;
            assert (checkRotationProof(msg.rotationSignature, msg.newPublicKey)) throw Errors.NewKeySignatureIsInvalid;
            acceptExternalMessage();

            storage.seqno += 1;
            storage.publicKey = msg.newPublicKey;
            storage.save();
        }

        else => {
            throw Errors.InvalidOpcode;
        }
    }
    // note: we don't need ENDS here, because an attack "hijack and append garbage to data"
    // is impossible: signature will mismatch
}

/// Returns current storage revision. It does not trigger migration.
/// After bytecode upgrade, returns the old revision until the first valid incoming message migrates `c4`.
get fun revision(): Revision {
    return getC4Revision()
}

/// Returns current seqno from the storage. Bumped on every valid incoming message.
get fun seqno(): uint32 {
    val storage = Storage.load();
    return storage.seqno;
}

/// Returns the subwallet id from the storage.
get fun get_subwallet_id(): uint32 {
    val storage = Storage.load();
    return storage.subwalletId;
}

/// Returns the public key corresponding to the signer's private key.
get fun get_public_key(): uint256 {
    val storage = Storage.load();
    return storage.publicKey;
}

import "errors"
import "messages"


/// Every client-provided message is sent via `sendRawMessage`, which appends an out action to c5.
fun MessageToSend.validateAndSend(self, isExternal: bool) {
    if (isExternal) {
        val hasIgnoreErrors = (self.sendMode & SEND_MODE_IGNORE_ERRORS) != 0;
        assert (hasIgnoreErrors) throw Errors.ExternalSendMessageMustHaveIgnoreErrorsSendMode;
    }
    // the most expensive line in WalletTg: 526 gas, it builds a cell for the c5-snake;
    // it's worse in gas than wallet-v5 which accepts raw c5 from a client,
    // but much CHEAPER in importFee, because
    // 1) each message is not wrapped to an extra cell
    // 2) bulk sending: 3 messages per chunk in an array, 3 times less incoming cells
    sendRawMessage(self.messageCell, self.sendMode);
}

/// Parse `array<MessageToSend>` encoded as a standard Tolk array, processing every message.
/// Instead of doing `array.fromSlice` (to a tuple of sub-tuples) + iterate this array,
/// parse-and-process on the fly: this is much cheaper.
/// We CAN throw here if an array is wrong-encoded ("cell underflow" and other parsing errors).
@inline
fun RawArrayOfMessagesToSend.parseArrayAndSend(self, isExternal: bool): slice {
    // self is raw slice encoded as an array: uint8 len + snaked chunks
    var cs = self;
    var count = 0;
    val len = cs.loadUint(8);
    var head = cs.loadMaybeRef();

    // we expect at least 1 message; an empty array (head == null) or malformed fails at beginParse
    head = head!;
    // do-while is cheaper than while
    do {
        // format of cur chunk: maybe ref to next chunk + N items
        var s = head.beginParse();
        head = s.loadMaybeRef();
        // possible:
        // 1 MessageToSend =  8 bits + 1 ref
        // 2 MessageToSend = 16 bits + 2 refs
        // 3 MessageToSend = 24 bits + 3 refs
        // 4 MessageToSend = 32 bits + 4 refs (last chunk, when no head ref)
        val chunkSize = s.remainingRefsCount();
        count += chunkSize;
        repeat (chunkSize) {
            val msg = s.loadAny<MessageToSend>();
            msg.validateAndSend(isExternal);
        }
        s.assertEnd();
    } while (head != null);

    // verify that encoded array len equals to actually provided chunks;
    // since len is uint8, there can't be more than 255 messages failing the action phase
    assert (count != 0) throw Errors.InvalidOutArrayLen;
    assert (count == len) throw Errors.InvalidOutArrayLen;
    // return what's following in "remaining", in case the caller needs this
    return cs;
}

/// Every time the contract logic is updated,
/// we append a new revision and provide a new storage migration.
/// Read `MIGRATION.md`.
enum Revision : uint8 {
    Rev00_Initial = 0,
}

const LAST_REVISION = Revision.Rev00_Initial

/// WalletTg can send up to 255 out messages.
/// Note: in contrast with w5, which accepts a well-formed c5 register, WalletTg accepts messages.
/// This is a clearer API, although it costs more gas unless WalletTg is precompiled.
struct MessageToSend {
    sendMode: uint8
    messageCell: cell
}

/// Bulk requests carry `array<MessageToSend>`, a standard-encoded Tolk array.
/// The contract parses it manually as a raw slice to avoid materializing the array.
type RawArrayOfMessagesToSend = RemainingBitsAndRefs

/// A payload signed by a new private key for the "change key" request.
struct KeyRotationProofPayload {
    private tag: uint96 = 0x4B45595F524F544154494F4E
    walletWorkchain: int8
    walletAddrHash: uint256
}

/// Every internal/external message is signed by a private key and checked against `storage.publicKey`.
/// The client-side signing process has three steps.
/// 1. Compose some valid request (body).
/// 2. Sign it with their private key (derived from a mnemonic) — resulting in `signature`.
/// 3. Prepend the signature to the serialized request and send.
///
/// Note that signing DIFFERS FROM WALLET V5, where signature lies at the end.
/// W5 is ABI-unfriendly: we can't describe "signature at the end" after RemainingBitsAndRefs.
/// Current (Telegram) version is Tolk-friendly, ABI-friendly, and client-friendly.
struct SignedRequest<T> {
    /// Signature of the body with the client's private key.
    signature: bits512
    /// Body of the incoming message (with opcode and data).
    request: T
}

/// Every internal/external request starts with a header.
/// For instance, it contains seqno to protect against replay attacks.
struct SeqnoHeader {
    /// Must match `Storage.subwalletId`, so one key can control multiple wallets.
    subwalletId: uint32
    /// Unix timestamp until which the message is valid. Must be greater than `blockchain.now`.
    /// Protects against replay after expiration.
    validUntil: uint32
    /// Seqno protects against replay attacks. Must match `Storage.seqno`.
    seqno: uint32
}

/// Check the signature and forward ONE message.
/// `MessageToSend` is stored inline, reducing import fee and gas.
/// Internal (not external) is used for gasless.
struct (0x63896E74) SendOneMessageRequestI {
    /// Header protects against replay attacks.
    header: SeqnoHeader
    /// A message to send. The contract builds c5 itself.
    msg: MessageToSend
}

/// Check the signature and forward ONE message.
/// Differs from "internal" struct only in opcode to prevent cross-channel replay.
struct (0x63896E75) SendOneMessageRequestE {
    /// Header protects against replay attacks.
    header: SeqnoHeader
    /// A message to send. The contract builds c5 itself.
    msg: MessageToSend
}

/// Check the signature and forward MANY messages (1-255).
/// Analogous to w5 "internal signed request".
/// Internal (not external) is used for gasless.
struct (0x73896E74) SendBulkMessagesRequestI {
    /// Header protects against replay attacks.
    header: SeqnoHeader
    /// Messages to send (1-255). The contract builds c5 itself.
    @abi.clientType(array<MessageToSend>)
    msgArr: RawArrayOfMessagesToSend
}

/// Check the signature and forward MANY messages (1-255).
/// Analogous to w5 "external signed request".
/// Differs from "internal" struct only in opcode to prevent cross-channel replay.
struct (0x73896E75) SendBulkMessagesRequestE {
    /// Header protects against replay attacks.
    header: SeqnoHeader
    /// Messages to send (1-255). The contract builds c5 itself.
    @abi.clientType(array<MessageToSend>)
    msgArr: RawArrayOfMessagesToSend
}

/// Change the wallet signing key.
/// Can be repeated: each request is signed by the current key and proven by the new key.
/// Internal (not external) is used for gasless.
struct (0xFBBA99C7) ChangePublicKeyRequestI {
    /// Header protects against replay attacks.
    header: SeqnoHeader
    /// Resets `Storage.publicKey` to this value.
    newPublicKey: uint256
    /// Signed `KeyRotationProofPayload`. The "change key" request is signed twice.
    /// First, by the current key (SignedRequest, the incoming message itself).
    /// Second, by the new key (rotation proof).
    rotationSignature: Cell<bits512>
}

/// Change the wallet signing key.
/// Can be repeated: each request is signed by the current key and proven by the new key.
/// Differs from "internal" struct only in opcode to prevent cross-channel replay.
struct (0xFBBA99C8) ChangePublicKeyRequestE {
    /// Header protects against replay attacks.
    header: SeqnoHeader
    /// Resets `Storage.publicKey` to this value.
    newPublicKey: uint256
    /// Signed `KeyRotationProofPayload`. The "change key" request is signed twice.
    /// First, by the current key (SignedRequest, the incoming message itself).
    /// Second, by the new key (rotation proof).
    rotationSignature: Cell<bits512>
}

import "migration"
import "revisions"

/// Current storage schema of the contract.
/// A new contract revision bumps its 0xXX prefix and may append new fields.
/// See `runMigrationAndUpdateC4` about migrations after bytecode upgrade.
struct (0x00) Storage {
    /// Seqno protects against replay attacks: every incoming message contains the expected seqno.
    /// Once the contract accepts a message, it bumps storage seqno. Old messages can't be replayed.
    seqno: uint32
    /// SubwalletId allows creating multiple wallets for one private key.
    /// Default for mainnet: 0x7FFF7F11; for testnet: 0x7FFF7FFD; for subwallets, consider docs.
    subwalletId: uint32
    /// Public key used to check signatures of all incoming messages.
    /// It can be replaced by a signed change-key request.
    publicKey: uint256
}

/// Every time the contract logic is updated, we bump 0xXX of `Storage`: it's the contract's revision.
/// After validator voting, new bytecode appears in config, atomically updating the "backend" of all Telegram wallets.
/// But c4 of each account still contains the previous revision number until migration.
fun getC4Revision(): Revision {
    // SAFETY: prefix of `Storage` is 0xXX
    return contract.getData().beginParse().loadUint(8) as Revision;
}

/// Loading storage means first ensuring that c4 has the last revision, then doing a regular load.
/// Note: it can't be used as `lazy` now because of extra logic besides "return fromCell".
/// Tolk v1.5 will support lazy here.
@inline
fun Storage.load(): Storage {
    if (getC4Revision() != LAST_REVISION) {
        runMigrationAndUpdateC4();
    }
    return Storage.fromCell(contract.getData(), {
        assertEndAfterReading: false,   // no ENDS, the cell is 100% correct; TODO: remove when lazy
    });
}

/// Update c4 with the current 0xXX-prefixed storage layout.
fun Storage.save(self) {
    contract.setData(self.toCell());
}


// -------------------------------------------------------
//     Old storage layouts: previous contract revisions
//
// Every wallet logic change is a "revision".
// Prefix 0xXX of `Storage` is the CURRENT (active) bytecode revision, stored in config.
//
// For every new revision (from XX to XX+1) we
// - copy `struct (0xXX) Storage` above to `struct (0xXX) OldStorage_XX` below
// - bump revision: `struct (0xXX+1) Storage` and in `contract` directive in `WalletTg.tolk`
// - provide a migration from XX to XX+1 in `migration.tolk`
// Even if storage shape did not change!!!
// Prefix of `Storage` must be equal to the last (active) one.
//
// Note: for the full migration algorithm, read `MIGRATION.md`; there are more points there.
//

type UnionOfOldStorages =
    | void

import "storage"

/// After a bytecode upgrade by validator voting, c4 contains old storage.
/// Its "c4 revision" is determined by the 0xXX prefix of c4.
/// Here we run the migration from the current c4 revision to LAST (from OldStorage_XX to Storage).
/// Runs at most once: it always does `contract.setData`.
@noinline
fun runMigrationAndUpdateC4(): void {
    // nothing to be done yet
    // later, we'll migrate UnionOfOldStorages to Storage
}
